tools.example:
model.component("comp1").physics().create("opt", "GeneralOptimization", "geom1");
model.component("comp1").physics("opt").create("lsobj1", "LeastSquaresObjective", 3);
model.component("comp1").physics("opt").feature("lsobj1").set("fileName", "C:/data/strain_gauges.csv");
// add CoordinateColumn x3, TimeColumn, ValueColumn in the order of the file

model.component("comp1").common().create("cfunc1", "ControlFunction");
model.component("comp1").common("cfunc1").set("name", "Pin");
model.component("comp1").common("cfunc1").set("xstart", "0");
model.component("comp1").common("cfunc1").set("xend", "600");
model.component("comp1").common("cfunc1").set("fmax", "1000");
model.component("comp1").common("cfunc1").set("controlType", "piecewiseBernsteinPolynomial");
// use Pin(t) as heater power; Application Library: optimal_heating_control, lib_charge_rate_optimization

model.component("comp1").common().create("std1", "StandardDeviation");
model.component("comp1").common("std1").selection().set(2);
model.component("comp1").common("std1").set("expression", "mf.normB");
// minimize the std1 variable in a Shape Optimization study (Application Library: coil_shape_optimization)

model.component("comp1").common().create("dtopo1", "DensityTopology");
model.component("comp1").common("dtopo1").selection().set(1);
model.component("comp1").common("dtopo1").set("filterLengthType", "Custom");
model.component("comp1").common("dtopo1").set("L_min", "2[mm]");
model.component("comp1").common("dtopo1").set("projectionType", "TanhProjection");
model.component("comp1").common("dtopo1").set("beta", "8");
model.component("comp1").common("dtopo1").set("interpolationType", "SIMP");
model.component("comp1").common("dtopo1").set("theta_0", "0.5");
// Young's modulus E = E0*dtopo1.theta_p (or via Topology Link)
